<script setup lang="ts">
import {ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {ElMessage} from 'element-plus';import {login,errorMessage} from '../api/http'
const router=useRouter(),route=useRoute();const username=ref(''),password=ref(''),loading=ref(false)
async function submit(){if(loading.value)return;if(!username.value||!password.value)return ElMessage.warning('ユーザー名とパスワードを入力してください');loading.value=true;try{await login(username.value,password.value);ElMessage.success('ログインしました');await router.replace(typeof route.query.redirect==='string'&&route.query.redirect.startsWith('/')&&!route.query.redirect.startsWith('//')&& !route.query.redirect.startsWith('/login')?route.query.redirect:'/exports')}catch(e){ElMessage.error(errorMessage(e))}finally{loading.value=false}}
</script>
<template><main class="login-wrap"><section class="login-card"><div class="login-logo">データ管理プラットフォーム</div><h2>ログイン</h2><p class="muted">輸出・販売管理システム</p><el-alert v-if="route.query.expired" title="セッションが切れました。再度ログインしてください。" type="warning" :closable="false"/><el-alert v-if="route.query.unavailable" title="サーバーに接続できません。起動状態を確認してください。" type="error" :closable="false"/><el-form @submit.prevent="submit" label-position="top"><el-form-item label="ユーザー名"><el-input v-model="username" autocomplete="username" placeholder="ユーザー名"/></el-form-item><el-form-item label="パスワード"><el-input v-model="password" type="password" show-password autocomplete="current-password" placeholder="パスワード" /></el-form-item><el-button type="primary" native-type="submit" size="large" :loading="loading" class="full-width">ログイン</el-button></el-form></section></main></template>
